// Controlled test content. It reports only bounded fixture counters and its
// own WebGL pixel; it exposes no browser automation or Native worker API.
import {createServer} from 'node:http';
import {randomUUID,createHash} from 'node:crypto';
import {PNG} from 'pngjs';
export async function startProductionNativePixelPage(){
 const id=randomUUID();let cycle=0,closed=false,latest=null,reportCount=0,imageRequests=0,stateRequests=0;const sockets=new Set();
 const html=`<!doctype html><meta charset="utf-8"><style>html,body{margin:0;background:white;font:18px sans-serif}input{position:absolute;left:20px;top:20px;width:260px;height:36px}#input,#cycle,#viewport{position:absolute;top:30px;width:24px;height:24px}#input{left:340px;background:rgb(0,0,42)}#cycle{left:400px}#viewport{left:520px}#edge{position:fixed;right:0;bottom:0;width:16px;height:16px;background:rgb(17,205,61)}#image{position:absolute;left:20px;top:80px;width:256px;height:256px}#gl{position:absolute;left:320px;top:200px;width:280px;height:100px}#normal{position:absolute;left:20px;top:350px}</style><input id="name"><div id="input"></div><div id="cycle"></div><div id="viewport"></div><div id="edge"></div><img id="image"><canvas id="gl" width="280" height="100"></canvas><canvas id="normal" width="64" height="32"></canvas><script>
 const root='/fixture/${id}',keys=new Set(),buttons=new Set();let current=-1,loaded=false,reportSeq=0;
 const gl=document.querySelector('#gl').getContext('webgl2',{preserveDrawingBuffer:true}),normal=document.querySelector('#normal').getContext('2d');if(gl){gl.clearColor(.1,.75,.25,1);gl.clear(gl.COLOR_BUFFER_BIT);gl.finish();}normal.fillStyle='rgb(31,79,191)';normal.fillRect(0,0,64,32);const pixel=new Uint8Array(4);if(gl)gl.readPixels(1,1,1,1,gl.RGBA,gl.UNSIGNED_BYTE,pixel);
 const report=()=>{if(++reportSeq>512)return;fetch(root+'/report',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({sequence:reportSeq,width:innerWidth,height:innerHeight,dpr:devicePixelRatio,inputLength:document.querySelector('input').value.length,heldKeys:keys.size,heldButtons:buttons.size,cycle:current,loaded,hasWebGL:!!gl,hasCanvas2D:!!normal,webglPixel:Array.from(pixel)})}).catch(()=>{});};
 const viewport=()=>{document.querySelector('#viewport').style.background='rgb('+(innerWidth&255)+','+(innerHeight&255)+',77)';report();};addEventListener('resize',viewport);viewport();
 document.querySelector('input').addEventListener('input',event=>{const n=event.target.value.length;document.querySelector('#input').style.background='rgb('+((n>>8)&255)+','+(n&255)+',42)';report();});
 for(const kind of ['keydown','keyup','mousedown','mouseup'])document.addEventListener(kind,event=>{if(kind==='keydown')keys.add(event.code);if(kind==='keyup')keys.delete(event.code);if(kind==='mousedown')buttons.add(event.button);if(kind==='mouseup')buttons.delete(event.button);queueMicrotask(report);});
 const update=async n=>{const image=document.querySelector('#image');image.src=root+'/image?n='+n;await image.decode();document.querySelector('#cycle').style.background='rgb('+(n&255)+','+((n>>8)&255)+',199)';current=n;loaded=true;report();};
 const poll=async()=>{try{const response=await fetch(root+'/state'),state=await response.json();if(state.cycle!==current)await update(state.cycle);}catch{}setTimeout(poll,50);};poll();
 </script>`;
 const image=n=>{const png=new PNG({width:256,height:256});let value=(n+1)>>>0;for(let i=0;i<png.data.length;i+=4){value^=value<<13;value^=value>>>17;value^=value<<5;png.data[i]=value&255;png.data[i+1]=(value>>>8)&255;png.data[i+2]=(value>>>16)&255;png.data[i+3]=255;}png.data.set([n&255,(n>>8)&255,199,255]);return PNG.sync.write(png,{deflateLevel:1,filterType:0});};
 const server=createServer(async(req,res)=>{try{res.setHeader('cache-control','no-store');const url=new URL(req.url,'http://fixture'),root='/fixture/'+id;if(closed||!url.pathname.startsWith(root)){res.writeHead(404);res.end();return;}
  if(req.method==='GET'&&url.pathname===root){res.setHeader('content-type','text/html; charset=utf-8');res.end(html);return;}
  if(req.method==='GET'&&url.pathname===root+'/state'){if(++stateRequests>10000)throw Error('Fixture request limit');res.setHeader('content-type','application/json');res.end(JSON.stringify({cycle}));return;}
  if(req.method==='GET'&&url.pathname===root+'/image'){const n=Number(url.searchParams.get('n'));if(!Number.isSafeInteger(n)||n<0||n>255||++imageRequests>64)throw Error('Fixture image bounds');res.setHeader('content-type','image/png');res.end(image(n));return;}
  if(req.method==='POST'&&url.pathname===root+'/report'){let text='';for await(const chunk of req){if(Buffer.byteLength(text)+chunk.length>2048)throw Error('Fixture body limit');text+=chunk;}const value=JSON.parse(text),fields=['sequence','width','height','dpr','inputLength','heldKeys','heldButtons','cycle','loaded','hasWebGL','hasCanvas2D','webglPixel'];if(++reportCount>512||Object.keys(value).sort().join()!==fields.sort().join()||!Number.isSafeInteger(value.sequence)||value.sequence<1||value.sequence>512||!['width','height','inputLength','heldKeys','heldButtons','cycle'].every(k=>Number.isSafeInteger(value[k]))||!Array.isArray(value.webglPixel)||value.webglPixel.length!==4||value.webglPixel.some(v=>!Number.isInteger(v)||v<0||v>255))throw Error('Fixture report limit');if(!latest||value.sequence>latest.sequence)latest=Object.freeze(value);res.writeHead(204);res.end();return;}
  res.writeHead(404);res.end();
 }catch{if(!res.headersSent)res.writeHead(400);res.end();}});
 server.on('connection',socket=>{sockets.add(socket);socket.on('error',()=>{});socket.once('close',()=>sockets.delete(socket));});await new Promise(r=>server.listen(0,'127.0.0.1',r));
 return {htmlSha256:createHash('sha256').update(html).digest('hex'),url:()=>`http://host.docker.internal:${server.address().port}/fixture/${id}`,get report(){return latest;},get cycle(){return cycle;},get listening(){return server.listening;},update(){if(closed||cycle>=255)throw Error('Fixture cycle bound');return ++cycle;},stats:()=>({reportCount,imageRequests,stateRequests,cycle,latest}),async close(){closed=true;for(const socket of sockets)socket.destroy();await new Promise(r=>server.close(r));}};
}
